package com.huy.enterprise.supplier; import com.huy.enterprise.common.*; import com.huy.enterprise.common.enums.*; import lombok.RequiredArgsConstructor; import org.springframework.stereotype.Service; import org.springframework.transaction.annotation.Transactional; import java.util.*; @Service @RequiredArgsConstructor @Transactional(readOnly=true) public class SupplierService {private final SupplierRepository repo; public List<SupplierResponse> all(RiskLevel risk){return (risk==null?repo.findAll():repo.findByRiskLevel(risk)).stream().map(SupplierResponse::from).toList();} public SupplierResponse get(UUID id){return SupplierResponse.from(entity(id));} Supplier entity(UUID id){return repo.findById(id).orElseThrow(()->new ResourceNotFoundException("Supplier not found: "+id));} @Transactional public SupplierResponse create(SupplierRequest r){if(repo.existsBySupplierCode(r.supplierCode()))throw new ConflictException("Supplier code already exists");return SupplierResponse.from(repo.save(apply(new Supplier(),r)));} @Transactional public SupplierResponse update(UUID id,SupplierRequest r){var s=entity(id);repo.findBySupplierCode(r.supplierCode()).filter(x->!x.getId().equals(id)).ifPresent(x->{throw new ConflictException("Supplier code already exists");});return SupplierResponse.from(repo.save(apply(s,r)));} @Transactional public void delete(UUID id){var s=entity(id);s.setStatus(RecordStatus.INACTIVE);repo.save(s);} private Supplier apply(Supplier s,SupplierRequest r){s.setSupplierCode(r.supplierCode());s.setName(r.name());s.setEmail(r.email());s.setPhone(r.phone());s.setAddress(r.address());s.setCountry(r.country());s.setRegion(r.region());s.setStatus(r.status()==null?RecordStatus.ACTIVE:r.status());s.setRiskLevel(r.riskLevel()==null?RiskLevel.LOW:r.riskLevel());s.setNotes(r.notes());return s;}}
